# Regenerate the PKCS#12 (.pfx) fixtures used by the T-0249 tests.
#
# The fixtures are *test-only* RSA keys generated by Windows itself, with a
# public password, so that PFX import is validated against an independent
# encoder (Windows PFXExportCertStoreEx) rather than against PDFXI's own writer.
# They carry no authority, sign nothing outside `cargo test`, and must never be
# installed into a real certificate store.
#
# Run from the repository root:
#   powershell -NoProfile -File crates/pdfxi-security/tests/fixtures/pfx/generate.ps1
#
# Windows PowerShell 5.1 / .NET Framework 4.8 is enough: the PKI module's
# Export-PfxCertificate exposes -CryptoAlgorithmOption, which is what produces
# the PBES2/AES-256 and PBES1/3DES variants this test set needs.
#
# Side effect: three certificates are created in Cert:\CurrentUser\My so the
# private keys can be exported, then removed again at the end.

$ErrorActionPreference = 'Stop'
$password = 'pdfxi-test-pfx'
$outDir = Split-Path -Parent $MyInvocation.MyCommand.Path
$validTo = (Get-Date).AddYears(5)
$created = @()

function New-TestCertificate {
    param(
        [string] $Subject,
        [string] $FriendlyName,
        [object] $Signer,
        [string[]] $TextExtension,
        [switch] $IsCa
    )
    $arguments = @{
        Subject           = $Subject
        FriendlyName      = $FriendlyName
        CertStoreLocation = 'Cert:\CurrentUser\My'
        KeyExportPolicy   = 'Exportable'
        KeyAlgorithm      = 'RSA'
        KeyLength         = 2048
        HashAlgorithm     = 'SHA256'
        NotAfter          = $validTo
    }
    if ($Signer) { $arguments.Signer = $Signer }
    if ($TextExtension) { $arguments.TextExtension = $TextExtension }
    if ($IsCa) { $arguments.KeyUsage = 'CertSign', 'CRLSign', 'DigitalSignature' }
    else { $arguments.KeyUsage = 'DigitalSignature' }
    $certificate = New-SelfSignedCertificate @arguments
    $script:created += $certificate
    return $certificate
}

$root = New-TestCertificate `
    -Subject 'CN=PDFXI Test Root CA, O=PDFXI' `
    -FriendlyName 'PDFXI T-0249 Root' `
    -IsCa `
    -TextExtension @('2.5.29.19={text}CA=true&pathlength=1')

$intermediate = New-TestCertificate `
    -Subject 'CN=PDFXI Test Intermediate CA, O=PDFXI' `
    -FriendlyName 'PDFXI T-0249 Intermediate' `
    -Signer $root `
    -IsCa `
    -TextExtension @('2.5.29.19={text}CA=true&pathlength=0')

$leaf = New-TestCertificate `
    -Subject 'CN=PDFXI Test Signing Identity, O=PDFXI' `
    -FriendlyName 'PDFXI T-0249 Leaf' `
    -Signer $intermediate `
    -TextExtension @('2.5.29.19={text}CA=false')

# PEM material for the trust-anchor bundle and for the CMS chain.
function Export-Pem {
    param([object] $Certificate, [string] $Name)
    $base64 = [Convert]::ToBase64String($Certificate.RawData, 'InsertLineBreaks')
    $pem = "-----BEGIN CERTIFICATE-----`r`n$base64`r`n-----END CERTIFICATE-----`r`n"
    [System.IO.File]::WriteAllText((Join-Path $outDir $Name), $pem)
}

Export-Pem $root 'root.pem'
Export-Pem $intermediate 'intermediate.pem'
Export-Pem $leaf 'leaf.pem'

# 3DES/SHA-1: PBES1 with the PKCS#12 key-derivation function, the legacy shape
# every older Windows and Java tool produces.
Export-PfxCertificate -Cert $leaf -FilePath (Join-Path $outDir 'leaf-3des.pfx') `
    -Password (ConvertTo-SecureString -String $password -Force -AsPlainText) `
    -CryptoAlgorithmOption TripleDES_SHA1 | Out-Null

# AES-256/SHA-256: PBES2 (PBKDF2 + AES-256-CBC), the modern shape.
Export-PfxCertificate -Cert $leaf -FilePath (Join-Path $outDir 'leaf-aes256.pfx') `
    -Password (ConvertTo-SecureString -String $password -Force -AsPlainText) `
    -CryptoAlgorithmOption AES256_SHA256 | Out-Null

# Remove the temporary private keys from the user store.
$created | ForEach-Object { Remove-Item -Path ("Cert:\CurrentUser\My\" + $_.Thumbprint) -Force }

Get-ChildItem $outDir | Select-Object Name, Length
